$target = Join-Path $PSScriptRoot '..\src\screens\QuranScreen.tsx'
$source = Get-Content -LiteralPath $target -Raw
$line = ' <View style={styles.recentRow}><View style={styles.recentCard}><View style={styles.arabicRound}><Text style={styles.roundArabic}>{"\u064A\u0633"}</Text></View><View style={{flex:1}}><Text style={styles.recentName}>{language==="bn"?bengaliTransliteration("Yasin"):"Yasin"}</Text><Text style={styles.recentMeta}>36 {t.ayahs}</Text></View><Icon name="book" size={23} color="#111"/></View><View style={styles.recentCard}><View style={styles.arabicRound}><Text style={styles.roundArabic}>{"\u0627\u0644\u0645\u0644\u0643"}</Text></View><View style={{flex:1}}><Text style={styles.recentName}>{language==="bn"?bengaliTransliteration("Al-Mulk"):"Al-Mulk"}</Text><Text style={styles.recentMeta}>30 {t.ayahs}</Text></View><Icon name="book" size={23} color="#111"/></View></View>'
$source = [regex]::Replace($source, '(?m)^ <View style=\{styles\.recentRow\}>.*$', $line)
Set-Content -LiteralPath $target -Value $source -Encoding utf8
